import React from "react";

export interface TelemetryMetric {
  readonly timestamp: number;
  readonly cpuUsage: number;
  readonly memoryUsage: number;
  readonly requestCount: number;
}

export interface TelemetryWidgetProps {
  readonly endpointUrl: string;
  readonly refreshIntervalMs?: number;
  readonly onAlert?: (metric: TelemetryMetric) => void;
}

export class TelemetryWidgetLegacy extends React.Component<TelemetryWidgetProps, { metrics: TelemetryMetric[]; isConnected: boolean }> {
  private intervalId: NodeJS.Timeout | null = null;

  constructor(props: TelemetryWidgetProps) {
    super(props);
    this.state = { metrics: [], isConnected: false };
  }

  componentDidMount() {
    this.intervalId = setInterval(() => {
      this.fetchMetrics();
    }, this.props.refreshIntervalMs ?? 2000);
  }

  componentWillUnmount() {
    if (this.intervalId) {
      clearInterval(this.intervalId);
    }
  }

  fetchMetrics() {
    fetch(this.props.endpointUrl)
      .then((res) => res.json())
      .then((data: TelemetryMetric) => {
        this.setState((prev) => ({
          metrics: [...prev.metrics.slice(-19), data],
          isConnected: true,
        }));
        if (data.cpuUsage > 90 && this.props.onAlert) {
          this.props.onAlert(data);
        }
      })
      .catch(() => {
        this.setState({ isConnected: false });
      });
  }

  render() {
    return (
      <div className="telemetry-widget">
        <h3>System Telemetry ({this.state.isConnected ? "Connected" : "Disconnected"})</h3>
        <ul>
          {this.state.metrics.map((m, idx) => (
            <li key={idx}>CPU: {m.cpuUsage}% | MEM: {m.memoryUsage}MB</li>
          ))}
        </ul>
      </div>
    );
  }
}

