package main

import (
	"encoding/json"
	"net/http"
	"time"
)

type MetricEvent struct {
	Timestamp    int64   `json:"timestamp"`
	CPUUsage     float64 `json:"cpuUsage"`
	MemoryUsage  float64 `json:"memoryUsage"`
	RequestCount int     `json:"requestCount"`
}

type TelemetryServer struct {
	metrics []MetricEvent
}

func NewTelemetryServer() *TelemetryServer {
	return &TelemetryServer{
		metrics: make([]MetricEvent, 0),
	}
}

func (s *TelemetryServer) HandleTelemetry(w http.ResponseWriter, r *http.Request) {
	event := MetricEvent{
		Timestamp:    time.Now().UnixMilli(),
		CPUUsage:     42.5,
		MemoryUsage:  256.0,
		RequestCount: 1200,
	}
	s.metrics = append(s.metrics, event)
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(event)
}

func main() {
	server := NewTelemetryServer()
	http.HandleFunc("/api/telemetry", server.HandleTelemetry)
	http.ListenAndServe(":8080", nil)
}
